bash -lc /bin/bash -c "python3 - <<'PY'
from pathlib import Path
import json,os
root=Path.cwd()
for name in ['native-unfamiliar-v52-passive-transfer','recovered-evidence','execution-builds','deliverables']:
 p=root/name
 total=0;n=0
 for f in p.rglob('*'):
  if 'node_modules' in f.parts or 'runtime' in f.relative_to(p).parts or f.is_symlink(): continue
  if f.is_file(): total+=f.stat().st_size;n+=1
 print(name,n,total)
for p in Path('/proc').iterdir():
 if p.name.isdigit():
  try:
   cmd=(p/'cmdline').read_bytes().split(b'\\0')
   if cmd and (cmd[0].endswith(b'/java') or cmd[0] in [b'node',b'python3']) and any(b'evaluate-minecraft' in c or b'server-1.21.4.jar' in c or b'library_upload.py' in c for c in cmd): print('task process',p.name,[c.decode(errors='replace') for c in cmd[:4]])
  except (FileNotFoundError,PermissionError):pass
PY"
